import * as M from './model.mjs';
const $=s=>document.querySelector(s),H=3600000,esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let s;try{s=JSON.parse(localStorage.getItem('leadflow-v1'));}catch{}if(!s||s.version!==1)s=M.seed();
let page='leads',filter='全部归我',query='',selected=null,taskFilter='今日与逾期',flowFilter='全部',period=30,teamFilter='全部团队',sourceFilter='全部来源',scopeIds=null;
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3a4 4 0 0 1 0 8"/><circle cx="9" cy="7" r="4"/>',tasks:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 9 1.5 1.5L12 8m2 2h3M8 16h9"/>',flow:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6.2 6.2a8 8 0 0 1 13.2 3M4.6 14.8a8 8 0 0 0 13.2 3"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',chart:'<path d="M4 3v18h17M8 16v-4m5 4V8m5 8V5"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=(n,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const fmt=t=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(t);
const day=t=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(t);
const due=t=>t<s.now?'逾期 '+(Math.round((s.now-t)/H*10)/10)+' 小时':day(t)===day(s.now)?'今日 '+fmt(t).split(' ')[1]:fmt(t);
const localDate=t=>{const d=new Date(t+8*H);return d.toISOString().slice(0,16);};
const dateValue=x=>Date.parse(x+':00+08:00');
const u=()=>M.person(s.user),owned=()=>s.leads.filter(l=>s.user==='mgr'||l.owner===s.user),ownTasks=()=>s.tasks.filter(t=>s.user==='mgr'||t.owner===s.user),lead=id=>s.leads.find(l=>l.id===id);
const color=x=>['活跃','已接收','已完成','高意向'].includes(x)?'green':['待接收','培育中','已预约','待办'].includes(x)?'orange':['已流失','已退回'].includes(x)?'red':['已试驾','进行中'].includes(x)?'blue':'purple';
const badge=x=>`<span class="badge ${color(x)}"><span class="dot"></span>${esc(x)}</span>`;
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function save(){M.scan(s);localStorage.setItem('leadflow-v1',JSON.stringify(s));}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function nav(){const mgr=s.user==='mgr';return (mgr?[['dashboard','chart','团队数据'],['leads','users','团队线索'],['tasks','tasks','团队任务'],['flow','flow','流转中心'],['revive','refresh','流失与激活']]:[['leads','users','我的线索'],['tasks','tasks','任务看板'],['flow','flow','流转中心'],['revive','refresh','流失与激活']]).map(([id,ic,label])=>`<button data-page="${id}" aria-label="${label}" title="${label}" class="${page===id?'active':''}">${icon(ic)}<div class="nav-text">${label}</div>${id==='tasks'?`<span>${ownTasks().filter(M.isOpen).length}</span>`:''}</button>`).join('');}
function render(){save();const title={leads:s.user==='mgr'?'团队线索':'我的线索',tasks:s.user==='mgr'?'团队任务':'任务看板',flow:'流转中心',dashboard:'团队数据看板',revive:'流失与激活',notifications:'消息提醒'}[page];$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('flow',23)}</div><div class="brand-text">LeadFlow</div></div><div class="nav-label">WORKSPACE / 工作空间</div><nav class="nav">${nav()}</nav><div class="sidebar-bottom"><div class="demo-note"><strong>每条线索，都有下一步</strong><br>从第一次咨询，到每一次交接。<br><button class="link" data-action="guide">查看演示路线 →</button></div><div class="side-user"><span class="avatar">${u().name.slice(-2)}</span><div><b>${u().name}</b><small>${u().team} · ${u().role}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">工作空间 <b>/ &nbsp; ${title}</b></div><div class="top-actions"><span class="demo-pill">INTERACTIVE DEMO</span><button class="icon" data-page="notifications" aria-label="消息提醒">${icon('bell')}${s.reminders.filter(r=>r.recipient===s.user&&!r.read&&M.isOpen(s.tasks.find(t=>t.id===r.task))).length?'<span class="hot"> · </span>':''}</button><select class="role-select" id="role" aria-label="切换演示角色">${M.users.map(x=>`<option value="${x.id}" ${x.id===s.user?'selected':''}>${x.name} · ${x.role}</option>`).join('')}</select><span class="avatar">${u().name.slice(-2)}</span></div></header><div class="content"><div class="heading"><div><div class="eyebrow">${page==='dashboard'?'TEAM OVERVIEW':'SALES WORKSPACE'}</div><h1>${title}</h1>${scopeIds?'<p class="tiny muted">已保留主管看板筛选条件 · 点击侧栏可清除</p>':''}<p class="subtitle">${page==='leads'?`早上好，${u().name}。让每一次跟进，都更进一步。`:page==='dashboard'?'看见流转效率，也看见每个需要关注的机会。':page==='tasks'?'把下一步变成行动。优先处理今日与逾期任务。':page==='flow'?'交接有回音，责任有归属，客户信息不断线。':page==='revive'?'让合适的机会，在合适的时间重新开始。':'到期提醒与异常升级，集中处理。'}</p></div><div class="actions">${btn(icon('flow',15)+' 演示路线','guide')}${page==='leads'?btn(icon('plus',15)+' 新建线索','new','primary'):''}</div></div>${page==='leads'?leadsPage():page==='tasks'?tasksPage():page==='flow'?flowPage():page==='dashboard'?dashboard():page==='revive'?revivePage():notifications()}<div class="demo-bar"><span>● 演示模式 · 虚构客户数据 · ${fmt(s.now)}（北京时间） · 操作仅保存在当前浏览器</span><div class="actions">${btn('+ 30 分钟','advance','', 'data-min="30"')}${btn('+ 1 天','advance','','data-min="1440"')}${btn('重置演示','reset')}</div></div></div></main>`;}
function stat(title,num,note,ic,action,warning=false){return `<button class="stat ${warning?'warning':''}" data-action="${action}"><div class="stat-top">${title}<span class="stat-icon">${icon(ic,16)}</span></div><div class="stat-num">${num}</div><div class="stat-note">${note}</div></button>`;}
function search(){return `<label class="search">${icon('search',14)}<input id="search" placeholder="搜索客户 / 车型" value="${esc(query)}" aria-label="搜索客户"></label>`;}
function filteredLeads(){let ls=s.leads.filter(l=>M.visible(s,l)&&(!scopeIds||scopeIds.has(l.id))); if(filter==='待接收')ls=ls.filter(l=>M.pending(s,l.id)&&(s.user==='mgr'||M.pending(s,l.id).to===s.user));else ls=ls.filter(l=>s.user==='mgr'||l.owner===s.user);if(['活跃','培育中','已流失','已成交'].includes(filter))ls=ls.filter(l=>l.life===filter);if(filter==='可复访')ls=ls.filter(l=>M.eligible(s,l));if(filter==='未分配')ls=ls.filter(l=>!l.owner);if(filter==='无下一步')ls=ls.filter(l=>l.life==='活跃'&&!M.tasksFor(s,l.id).length);return ls.filter(l=>(l.name+l.id+l.model+l.source).includes(query));}
function table(ls){return `<div class="table-wrap"><table><thead><tr><th>客户 / 线索编号</th><th>意向车型</th><th>当前进展</th><th>下一步任务</th><th>负责人</th><th></th></tr></thead><tbody>${ls.map(l=>{const t=M.tasksFor(s,l.id).sort((a,b)=>a.due-b.due)[0],x=M.pending(s,l.id);return `<tr data-lead="${l.id}" tabindex="0" aria-label="查看${l.name}"><td><div class="client"><span class="avatar">${l.name.slice(0,1)}</span><div><b>${l.name}</b><small>${l.id} · ${l.source}</small></div></div></td><td>${esc(l.model)}<small>${l.budget}</small></td><td>${badge(l.life==='活跃'?l.stage:l.life)}<small>${x?'↗ 待 '+M.person(x.to).name+' 接收':l.intent}</small></td><td>${t?esc(t.type):'—'}<small class="${t?.due<s.now?'hot':''}">${t?due(t.due):l.life==='已流失'?esc(l.reason):'暂无待办'}</small></td><td>${l.owner?M.person(l.owner).name:'待分配'}<small>${l.team}</small></td><td class="muted">›</td></tr>`;}).join('')}</tbody></table>${!ls.length?'<div class="empty">暂无符合条件的线索</div>':''}</div><div class="table-foot"><span>共 ${ls.length} 条线索</span><span>点击客户查看详情与操作 →</span></div>`;}
function leadsPage(){const ls=owned(),ts=ownTasks().filter(M.isOpen),incoming=s.transfers.filter(x=>x.status==='待接收'&&(s.user==='mgr'||x.to===s.user));return `<div class="stats">${stat('活跃线索',ls.filter(l=>l.life==='活跃').length,'当前由你负责的购车机会','users','filter-active')}${stat('待接收交接',incoming.length,'客户信息与任务一同交接','flow','filter-incoming')}${stat('今日待办',ts.filter(t=>day(t.due)===day(s.now)).length,'每一次行动，都指向下一步','tasks','today')}${stat('逾期任务',ts.filter(t=>t.due<s.now).length,'优先处理，避免客户等待','clock','overdue',true)}</div><div class="grid-main"><section class="panel"><div class="panel-head"><h2>线索列表 <small> / LEADS</small></h2><small>当前归属实时更新</small></div><div class="filters"><div class="tabs">${['全部归我','活跃','待接收','培育中','已流失'].map(f=>btn(f,'filter',f===filter?'active':'',`data-value="${f}"`)).join('')}</div>${search()}</div>${table(filteredLeads())}</section><aside class="rail">${rail(ts,incoming)}</aside></div>`;}
function rail(ts,incoming){const top=[...ts].sort((a,b)=>a.due-b.due).slice(0,3);return `<section class="panel"><div class="panel-head"><h2>今日优先</h2>${btn('查看全部 →','today','link')}</div><div class="rail-body">${ts.some(t=>t.due<s.now)?`<div class="notice">${icon('clock',14)} 有 ${ts.filter(t=>t.due<s.now).length} 项任务已逾期<br>及时跟进，让客户少等一步。</div>`:''}${top.map(t=>`<div class="mini-task"><span class="checkbox"></span><div><p>${lead(t.lead).name} · ${t.type}</p><small>${due(t.due)}</small><br>${btn('去处理 →','task','link',`data-id="${t.id}"`)}</div></div>`).join('')||'<div class="empty">暂时没有待处理任务</div>'}</div></section><section class="panel"><div class="panel-head"><h2>交接不断线</h2>${icon('flow',16)}</div><div class="rail-body"><p class="tiny muted" style="margin-top:0">信息随线索流转，任务随负责人迁移。</p><div class="flow"><span>线上</span>→<span>门店</span>→<span>销售</span></div><div class="progress"><i style="width:${incoming.length?45:100}%"></i></div><small class="tiny muted">${incoming.length} 条交接等待接收</small><div style="margin-top:15px">${btn('进入流转中心 →','flow','link')}</div></div></section>`;}
function tasksPage(){let ts=ownTasks().filter(t=>t.status!=='已取消'&&(!scopeIds||scopeIds.has(t.lead)));if(taskFilter==='今日与逾期')ts=ts.filter(t=>day(t.due)===day(s.now)||(t.due<s.now&&M.isOpen(t)));if(taskFilter==='逾期')ts=ts.filter(t=>M.isOpen(t)&&t.due<s.now);return `<div class="filters" style="padding:0 0 20px;border:0"><div class="tabs">${['今日与逾期','全部任务','逾期'].map(f=>btn(f,'task-filter',taskFilter===f?'active':'',`data-value="${f}"`)).join('')}</div><span class="tiny muted">逾期是时间标记，不改变任务状态</span></div><div class="kanban">${['待办','进行中','已完成'].map(status=>{const list=ts.filter(t=>t.status===status).sort((a,b)=>a.due-b.due);return `<section class="column"><div class="col-title"><b>${status}</b><span>${list.length}</span></div>${list.map(t=>`<article class="task-card"><div class="actions">${badge(t.type)}${t.delays.length?'<span class="tiny muted">延期 '+t.delays.length+' 次</span>':''}</div><h3>${lead(t.lead).name}</h3><p>${lead(t.lead).model} · ${M.person(t.owner).name}</p><div class="due ${t.due<s.now&&M.isOpen(t)?'over':''}"><span>${icon('clock',12)} ${due(t.due)}</span><span>${lead(t.lead).id}</span></div><div class="actions">${M.isOpen(t)?btn('处理任务','task','primary',`data-id="${t.id}"`)+(status==='待办'?btn('开始','start','',`data-id="${t.id}"`):'')+btn('延期','postpone','',`data-id="${t.id}"`):`<span class="tiny muted">${esc(t.result||'已完成')}</span>`}${btn('客户详情','detail','link',`data-id="${t.lead}"`)}</div></article>`).join('')||'<div class="empty">这一列暂时没有任务</div>'}</section>`;}).join('')}</div>`;}
function flowPage(){const xs=s.transfers.filter(x=>s.user==='mgr'||x.from===s.user||x.to===s.user).filter(x=>!scopeIds||scopeIds.has(x.lead)).filter(x=>flowFilter==='全部'||(flowFilter==='超时'?x.status==='待接收'&&x.due<s.now:x.status===flowFilter));return `<section class="panel"><div class="panel-head"><h2>每一次交接，都有记录</h2><small>接收前，原负责人继续负责</small></div><div class="filters"><div class="tabs">${['全部','待接收','已接收','已退回','超时'].map(f=>btn(f,'flow-filter',f===flowFilter?'active':'',`data-value="${f}"`)).join('')}</div></div>${xs.map(x=>`<div class="transfer-card"><div><h3>${lead(x.lead).name}</h3><p>${lead(x.lead).model} · ${x.lead}</p></div><div><div class="transfer-route">${x.from?M.person(x.from).name:'团队池'} ${icon('arrow',15)} ${M.person(x.to).name}</div><p>${x.fromTeam} → ${M.person(x.to).team}</p><p>${esc(x.reason)}</p></div><div>${badge(x.status)}<p class="${x.due<s.now&&x.status==='待接收'?'hot':''}">${x.status==='待接收'?due(x.due):fmt(x.end)}</p></div>${btn('查看交接','detail','',`data-id="${x.lead}"`)}</div>`).join('')||'<div class="empty">暂无交接记录</div>'}</section>`;}
function revivePage(){const ls=owned().filter(l=>['已流失','培育中'].includes(l.life)&&(!scopeIds||scopeIds.has(l.id)));return `<div class="stats">${stat('已流失',ls.filter(l=>l.life==='已流失').length,'保留流失原因与历史','users','lost')}${stat('可复访',ls.filter(l=>M.eligible(s,l)).length,'冷却期结束，不等于已激活','refresh','eligible')}${stat('培育中',ls.filter(l=>l.life==='培育中').length,'按约定时间再次沟通','clock','nurture')}${stat('已激活周期',s.events.filter(e=>e.action==='重新激活'&&owned().some(l=>l.id===e.lead)).length,'新周期，不重复计算获客','chart','activation-list')}</div><section class="panel"><div class="panel-head"><h2>机会可以重启，历史不会丢失</h2>${s.user==='mgr'?btn('为可复访线索创建任务','batch-revisit','primary'):''}</div><div class="filters"><div class="tabs">${['全部','可复访','培育中','已流失'].map(f=>btn(f,'revive-filter',filter===f?'active':'',`data-value="${f}"`)).join('')}</div><span class="tiny muted">明确拒绝联系与无效信息不会进入常规复访名单</span></div>${table(ls.filter(l=>filter==='可复访'?M.eligible(s,l):['培育中','已流失'].includes(filter)?l.life===filter:true))}</section>`;}
function dashboard(){const ls=s.leads.filter(l=>(teamFilter==='全部团队'||l.team===teamFilter)&&(sourceFilter==='全部来源'||l.source===sourceFilter)),ids=new Set(ls.map(l=>l.id)),ts=s.tasks.filter(t=>ids.has(t.lead)),xs=s.transfers.filter(x=>ids.has(x.lead)&&x.at>=s.now-period*24*H),ev=s.events.filter(e=>ids.has(e.lead)&&e.at>=s.now-period*24*H&&e.at<=s.now),accepted=xs.filter(x=>x.status==='已接收'),hours=accepted.map(x=>(x.end-x.at)/H).sort((a,b)=>a-b),median=hours.length?(hours[Math.floor((hours.length-1)/2)]+hours[Math.ceil((hours.length-1)/2)])/2:null;const reasons={};ev.filter(e=>e.action==='标记流失').forEach(e=>reasons[e.text]=(reasons[e.text]||0)+1);const activated=ev.filter(e=>e.action==='重新激活'),effective=activated.filter(a=>s.events.some(e=>e.cycle===a.cycle&&e.effective));return `<div class="filters" style="padding:0 0 20px;border:0"><select id="period" class="period-select" aria-label="统计日期">${[1,7,30].map(d=>`<option value="${d}" ${d===period?'selected':''}>近 ${d} 天</option>`).join('')}</select><select id="team-filter" class="period-select" aria-label="团队筛选">${['全部团队','线上直营','杭州湖滨店','杭州滨江店'].map(t=>`<option ${t===teamFilter?'selected':''}>${t}</option>`).join('')}</select><select id="source-filter" class="period-select" aria-label="来源筛选">${['全部来源','品牌小程序','品牌官网','自然到店','品牌活动'].map(t=>`<option ${t===sourceFilter?'selected':''}>${t}</option>`).join('')}</select><span class="tiny muted">趋势按所选期间 · 以下异常卡片为截至当前快照 · 团队筛选按当前归属</span></div><div class="stats">${stat('待分配线索',ls.filter(l=>!l.owner).length,'主管负责团队池内分配','users','unassigned')}${stat('交接超时',s.transfers.filter(x=>ids.has(x.lead)&&x.status==='待接收'&&x.due<s.now).length,'下钻查看待处理交接','flow','transfer-overdue',true)}${stat('逾期任务',ts.filter(t=>M.isOpen(t)&&t.due<s.now).length,'查看任务与延期记录','clock','overdue',true)}${stat('无下一步线索',ls.filter(l=>l.life==='活跃'&&!M.tasksFor(s,l.id).length).length,'活跃线索必须有下一步','tasks','no-next')}</div><div class="dash-grid"><section class="panel"><div class="panel-head"><h2>流转效率</h2><small>所选期间发起的交接</small></div><div class="rail-body"><div class="metric-pair"><div class="tiny muted">接收率<b style="color:var(--green)">${xs.length?Math.round(100*accepted.length/xs.length)+'%':'—'}</b>${accepted.length} 已接收 / ${xs.length} 全部发起</div><div class="tiny muted">接收耗时中位数<b style="color:var(--ink)">${median===null?'—':median.toFixed(1)+'h'}</b>仅统计已接收交接</div></div>${['待接收','已接收','已退回','已撤回'].map(k=>chart(k,xs.filter(x=>x.status===k).length,xs.length)).join('')}${btn('查看全部交接 →','flow','link')}</div></section><section class="panel"><div class="panel-head"><h2>流失与激活</h2><small>按跟进周期记录事件</small></div><div class="rail-body"><div class="metric-pair"><div class="tiny muted">期间激活<b>${activated.length}</b>不计入新增获客</div><div class="tiny muted">激活后有效联系率<b>${activated.length?Math.round(effective.length/activated.length*100)+'%':'—'}</b>${effective.length} 个周期已有效联系</div></div>${Object.entries(reasons).length?Object.entries(reasons).map(([k,n])=>chart(k,n,Object.values(reasons).reduce((a,b)=>a+b,0))).join(''):'<div class="empty">所选期间暂无流失事件</div>'}${btn('查看流失与激活 →','revive','link')}</div></section></div><section class="panel"><div class="panel-head"><h2>销售负载</h2><small>当前负责人归属 · 点击销售查看线索</small></div><div class="table-wrap"><table><thead><tr><th>销售 / 团队</th><th>活跃线索</th><th>待接收</th><th>今日任务</th><th>逾期任务</th><th>负载分布</th></tr></thead><tbody>${M.users.filter(x=>x.id!=='mgr').map(x=>{const n=ls.filter(l=>l.owner===x.id&&l.life==='活跃').length;return `<tr data-owner="${x.id}"><td><b>${x.name}</b><small>${x.team}</small></td><td>${n}</td><td>${s.transfers.filter(t=>ids.has(t.lead)&&t.to===x.id&&t.status==='待接收').length}</td><td>${ts.filter(t=>t.owner===x.id&&M.isOpen(t)&&day(t.due)===day(s.now)).length}</td><td>${ts.filter(t=>t.owner===x.id&&M.isOpen(t)&&t.due<s.now).length}</td><td><div class="progress" style="width:130px"><i style="width:${Math.min(n/10*100,100)}%"></i></div></td></tr>`;}).join('')}</tbody></table></div></section><div style="height:20px"></div><section class="panel"><div class="panel-head"><h2>购车阶段到达</h2><small>期间新建周期 · 跳级不补造事件</small></div><div class="rail-body">${['新咨询','已联系','已预约','已到店','已试驾','已成交'].map(stage=>{const cycles=new Set(ev.filter(e=>['线索创建','重新激活'].includes(e.action)).map(e=>e.cycle));const n=new Set(s.events.filter(e=>cycles.has(e.cycle)&&e.stage===stage).map(e=>e.cycle)).size;return chart(stage,n,cycles.size);}).join('')}</div></section>`;}
function chart(label,n,total){return `<div class="chart-row"><span>${esc(label)}</span><div class="bar-track"><div class="bar-fill" style="width:${total?Math.min(100,n/total*100):0}%"></div></div><b>${n}</b></div>`;}
function notifications(){const rs=s.reminders.filter(r=>r.recipient===s.user&&M.isOpen(s.tasks.find(t=>t.id===r.task))).sort((a,b)=>b.at-a.at);return `<section class="panel"><div class="panel-head"><h2>当前任务提醒</h2>${btn('全部标为已读','read-all')}</div>${rs.map(r=>{const t=s.tasks.find(t=>t.id===r.task);return `<div class="notification"><div>${badge(r.level)} <span class="tiny muted">${r.read?'已读':'未读'} · ${fmt(r.at)}</span><p>${lead(t.lead).name} · ${t.type}</p></div>${btn('处理','task','',`data-id="${t.id}"`)}</div>`;}).join('')||'<div class="empty">当前没有提醒</div>'}</section>`;}
function showDetail(id){selected=id;const l=lead(id),x=M.pending(s,id),can=s.user==='mgr'||l.owner===s.user;$('#overlay').innerHTML=`<div class="backdrop" data-action="close"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="线索详情"><div class="drawer-head"><span class="tiny muted">线索详情 / ${l.id}</span>${btn(icon('close'),'close','icon','aria-label="关闭详情"')}</div><div class="drawer-body"><div class="profile"><span class="avatar">${l.name[0]}</span><div><h2>${esc(l.name)}</h2>${badge(l.life)} ${badge(l.stage)}</div></div><div class="detail-grid"><div><small>当前负责人</small><b>${l.owner?M.person(l.owner).name:'团队待分配池'} · ${l.team}</b></div><div><small>原始来源</small><b>${l.source}</b></div><div><small>意向车型 / 预算</small><b>${l.model} / ${l.budget}</b></div><div><small>联系方式</small><b>${l.phone}${!l.allowed?' · 禁止联系':''}${!l.valid?' · 待修正':''}</b></div></div><div class="summary"><b>沟通摘要</b><br>${esc(l.summary)}</div>${x?`<div class="notice"><b>待 ${M.person(x.to).name} 接收</b> · ${due(x.due)}<br>${esc(x.summary)}<br>下一步：${esc(x.next)}<div class="actions" style="margin-top:12px">${s.user===x.to||s.user==='mgr'?btn('接收线索','accept','primary')+btn('退回','reject'):''}${can?btn('撤回交接','withdraw'):''}</div></div>`:''}<div class="actions" style="margin-top:20px">${can&&['活跃','培育中'].includes(l.life)?btn(l.owner?'转交线索':'分配线索','transfer','primary')+btn('安排试驾','appointment')+btn('转为培育','nurture')+btn('标记流失','lose','danger')+btn('标记成交','won'):''}${can&&['已流失','培育中'].includes(l.life)?btn('重新激活','activate','primary'):''}${can&&M.eligible(s,l)?btn('安排复访','revisit'):''}${s.user==='mgr'&&['活跃','培育中'].includes(l.life)&&l.owner?btn('回收至团队池','reclaim'):''}</div>${l.reason?`<p class="form-note">${l.life==='活跃'?'历史状态原因':'状态原因'}：${esc(l.reason)}${l.life==='已流失'?'<br>冷却结束仅允许复访，客户确认新意向后才激活。':''}</p>`:''}<h3 class="section-label">下一步任务 <span class="muted">${M.tasksFor(s,id).length} 项</span></h3>${M.tasksFor(s,id).map(t=>`<div class="mini-task"><span class="checkbox"></span><div style="flex:1"><p>${t.type} · ${M.person(t.owner).name}</p><small>${due(t.due)}${t.delays.length?' · 已延期 '+t.delays.length+' 次':''}</small></div>${btn('处理','task','link',`data-id="${t.id}"`)}</div>`).join('')||'<p class="form-note">当前状态无日常跟进任务</p>'}<h3 class="section-label">完整流转与跟进记录</h3><div class="timeline">${s.events.filter(e=>e.lead===id).sort((a,b)=>b.at-a.at||b.id.localeCompare(a.id)).map(e=>`<div class="event"><b>${e.action}</b><p>${esc(e.text)}</p><small>${fmt(e.at)} · ${M.person(e.actor)?.name||'系统'}</small></div>`).join('')}</div></div></aside>`;}
const input=(name,label,value='',type='text')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" required></div>`;
const area=(name,label,value='')=>`<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" required>${esc(value)}</textarea></div>`;
const select=(name,label,values)=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${values.map(v=>`<option value="${esc(Array.isArray(v)?v[0]:v)}">${esc(Array.isArray(v)?v[1]:v)}</option>`).join('')}</select></div>`;
function modal(title,body,onSubmit,label='确认'){const old=$('.modal');if(old)old.remove();const el=document.createElement('div');el.className='modal';el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.innerHTML=`<header><h2>${title}</h2>${btn(icon('close'),'close-modal','icon','aria-label="关闭表单"')}</header><form>${body}<div class="form-error" role="alert"></div><footer>${btn('取消','close-modal')}<button type="submit" class="primary">${label}</button></footer></form>`;if(!$('.backdrop'))$('#overlay').innerHTML='<div class="backdrop" data-action="close"></div>';$('#overlay').append(el);el.querySelectorAll('button[data-action]').forEach(b=>b.type='button');el.querySelector('form').onsubmit=e=>{e.preventDefault();try{onSubmit(Object.fromEntries(new FormData(e.target)));save();render();if(selected)showDetail(selected);else $('#overlay').innerHTML='';toast('已保存，相关任务与记录已更新');}catch(err){el.querySelector('.form-error').textContent=err.message;}};el.querySelector('input,textarea,select')?.focus();}
function guide(){modal('6–8 分钟演示路线',`<div class="guide-step"><b>1</b><div>以林悦身份打开陈女士线索，转给湖滨店周辰。切换周辰接收，再转给同店许宁。</div></div><div class="guide-step"><b>2</b><div>切换许宁，查看迁移后的任务并安排试驾。在流转中心查看线上与门店的双向交接。</div></div><div class="guide-step"><b>3</b><div>切换林悦，在“流失与激活”中打开王先生，记录新意向并激活。</div></div><div class="guide-step"><b>4</b><div>切换主管沈知行，从数据看板下钻查看超时、未分配线索和销售负载。</div></div><p class="form-note">底部可推进演示时钟。重置会清除当前浏览器的演示操作并恢复初始案例。</p>`,()=>{},'开始体验');}
function perform(action,el){if(page==='dashboard'&&['unassigned','no-next','overdue','transfer-overdue','flow','revive'].includes(action))scopeIds=new Set(s.leads.filter(l=>(teamFilter==='全部团队'||l.team===teamFilter)&&(sourceFilter==='全部来源'||l.source===sourceFilter)).map(l=>l.id));const id=el?.dataset.id,l=selected?lead(selected):null;switch(action){
case 'close':selected=null;$('#overlay').innerHTML='';return;
case 'close-modal':$('.modal')?.remove();if(!$('.drawer'))$('#overlay').innerHTML='';return;
case 'guide':guide();return;
case 'detail':showDetail(id);return;
case 'filter':filter=el.dataset.value;break;
case 'filter-active':filter='活跃';page='leads';break;
case 'filter-incoming':filter='待接收';page='leads';break;
case 'today':page='tasks';taskFilter='今日与逾期';break;
case 'overdue':page='tasks';taskFilter='逾期';break;
case 'task-filter':taskFilter=el.dataset.value;break;
case 'flow-filter':flowFilter=el.dataset.value;break;
case 'revive-filter':filter=el.dataset.value;break;
case 'flow':page='flow';flowFilter='全部';break;
case 'revive':page='revive';filter='全部';break;
case 'lost':page='revive';filter='已流失';break;
case 'eligible':page='revive';filter='可复访';break;
case 'nurture':if(!selected){page='revive';filter='培育中';break;}modal('转为培育',area('reason','培育原因')+input('date','复访时间（北京时间）',localDate(s.now+7*24*H),'datetime-local'),f=>M.lifecycle(s,l.id,'培育中',f.reason,dateValue(f.date)));return;
case 'unassigned':filter='未分配';page='leads';break;
case 'no-next':filter='无下一步';page='leads';break;
case 'transfer-overdue':page='flow';flowFilter='超时';break;
case 'activation-list':{const ids=new Set(s.events.filter(e=>e.action==='重新激活').map(e=>e.lead));modal('已激活线索',table(owned().filter(l=>ids.has(l.id))),()=>{},'关闭');return;}
case 'advance':s.now+=Number(el.dataset.min)*60000;toast('演示时钟已推进，提醒已刷新');break;
case 'reset':modal('重置演示数据','<p class="form-note">这会清除本浏览器中的模拟操作，恢复初始客户、任务与演示时钟。</p>',()=>{s=M.seed();selected=null;page='leads';filter='全部归我';query='';},'确认重置');return;
case 'read-all':s.reminders.filter(r=>r.recipient===s.user).forEach(r=>r.read=true);break;
case 'new':modal('新建线索',input('name','客户称呼')+select('source','线索来源',['品牌小程序','品牌官网','自然到店','品牌活动'])+select('model','意向车型',['E5 长续航','E7 四驱版','E5 标准版']),f=>{selected=M.newLead(s,f.name,f.source,f.model).id;});return;
case 'transfer':modal(l.owner?'转交线索':'分配线索',select('to','接收销售',M.users.filter(x=>x.id!=='mgr'&&x.id!==l.owner).map(x=>[x.id,x.name+' · '+x.team]))+area('reason','交接原因')+area('summary','沟通摘要',l.summary)+input('next','建议下一步','联系客户，确认到店安排')+'<p class="form-note">对方接收前，当前负责人继续负责。接收后未完成任务自动迁移。</p>',f=>M.transfer(s,l.id,f.to,f.reason,f.summary,f.next),'发起交接');return;
case 'accept':M.resolve(s,l.id,'已接收');break;
case 'reject':modal('退回交接',area('reason','退回原因'),f=>M.resolve(s,l.id,'已退回',f.reason));return;
case 'withdraw':M.resolve(s,l.id,'已撤回','发起人撤回交接');break;
case 'reclaim':modal('回收至团队池',area('reason','回收原因')+'<p class="form-note">线索与未完成任务进入团队池，由主管继续负责并重新分配。</p>',f=>M.reclaim(s,l.id,f.reason));return;
case 'lose':modal('标记流失',select('reason','流失原因',['预算不符','产品不匹配','已购竞品','购车计划取消','持续无法联系','明确拒绝联系','无效联系方式','其他'])+area('note','补充说明')+'<label class="check-field"><input type="checkbox" name="allowed" checked>客户允许后续联系</label><p class="form-note">将结束待接收交接，取消未完成联系任务与模拟预约，并保留全部历史。</p>',f=>{M.lifecycle(s,l.id,'已流失',f.reason,null,!!f.allowed);M.event(s,l,'流失说明',f.note);});return;
case 'won':modal('标记成交',area('reason','成交说明')+'<p class="form-note">结束本次购车机会，取消剩余任务及模拟预约。</p>',f=>M.lifecycle(s,l.id,'已成交',f.reason));return;
case 'activate':modal('重新激活线索',area('reason','客户的新意向与激活依据')+(!l.allowed?'<label class="check-field"><input name="consent" type="checkbox">客户主动联系，并明确同意恢复后续联系（记录模拟事件）</label>':'')+(!l.valid?'<label class="check-field"><input name="corrected" type="checkbox">已核实并修正模拟联系方式</label>':'')+'<p class="form-note">新建跟进周期与联系任务，保留此前流失原因和跟进历史。</p>',f=>M.activate(s,l.id,f.reason,{consent:!!f.consent,corrected:!!f.corrected}),'确认激活');return;
case 'revisit':M.revisit(s,l.id);break;
case 'batch-revisit':{const ls=owned().filter(l=>M.eligible(s,l)&&!M.tasksFor(s,l.id).some(t=>t.type==='流失复访'));if(!ls.length){toast('暂无可新建复访任务的线索');return;}ls.forEach(l=>M.revisit(s,l.id));toast('已创建 '+ls.length+' 条复访任务，尚未激活客户');break;}
case 'appointment':modal('安排试驾',input('date','试驾时间（北京时间）',localDate(s.now+5*24*H),'datetime-local')+'<p class="form-note">保存模拟预约，并生成提前确认任务；不预订真实车辆资源。</p>',f=>M.appointment(s,l.id,dateValue(f.date)));return;
case 'start':{const t=s.tasks.find(t=>t.id===id);if(t.owner!==s.user&&s.user!=='mgr')throw Error('无权处理');if(!M.isOpen(t))throw Error('任务已结束');t.status='进行中';break;}
case 'postpone':modal('延期任务',input('date','新的截止时间',localDate(Math.max(s.now,s.tasks.find(t=>t.id===id).due)+24*H),'datetime-local')+area('reason','延期原因'),f=>M.postpone(s,id,dateValue(f.date),f.reason));return;
case 'task':{const t=s.tasks.find(t=>t.id===id);if(t.type==='接收线索'||t.type==='分配线索'){showDetail(t.lead);return;}selected=t.lead;modal('完成任务 · '+lead(t.lead).name,select('result','跟进结果',['有效联系','未接通','已完成安排'])+area('note','跟进记录')+input('next','下一步任务','客户跟进')+input('date','下次任务时间',localDate(s.now+24*H),'datetime-local')+select('stage','购车阶段',[lead(t.lead).stage,...['已联系','已预约','已到店','已试驾'].filter(v=>v!==lead(t.lead).stage)])+'<p class="form-note">未接通只完成本次联系尝试，不会推进购车阶段。确认新意向后请在线索详情中激活。</p>',f=>{M.finish(s,id,f.result,f.stage==='已试驾'?'试驾后回访':f.next,dateValue(f.date),f.stage);M.event(s,lead(t.lead),'沟通记录',f.note);});return;}
}render();if(selected)showDetail(selected);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){try{perform(b.dataset.action,b);}catch(err){toast(err.message);}return;}const n=e.target.closest('[data-page]');if(n){page=n.dataset.page;scopeIds=null;selected=null;filter=page==='revive'?'全部':'全部归我';query='';$('#overlay').innerHTML='';render();window.scrollTo(0,0);return;}const row=e.target.closest('[data-lead]');if(row){showDetail(row.dataset.lead);return;}const owner=e.target.closest('[data-owner]');if(owner){modal(M.person(owner.dataset.owner).name+' · 当前线索',table(s.leads.filter(l=>l.owner===owner.dataset.owner&&(teamFilter==='全部团队'||l.team===teamFilter)&&(sourceFilter==='全部来源'||l.source===sourceFilter))),()=>{},'关闭');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('.modal'))perform('close-modal');else perform('close');}if(e.key==='Enter'&&e.target.matches('[data-lead]'))showDetail(e.target.dataset.lead);});
document.addEventListener('change',e=>{if(e.target.id==='role'){s.user=e.target.value;scopeIds=null;page=s.user==='mgr'?'dashboard':'leads';filter='全部归我';query='';selected=null;$('#overlay').innerHTML='';}else if(e.target.id==='period')period=+e.target.value;else if(e.target.id==='team-filter')teamFilter=e.target.value;else if(e.target.id==='source-filter')sourceFilter=e.target.value;else return;render();window.scrollTo(0,0);});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
render();
